solutions.naive:
class Solution:
    def successfulPairs(self, spells: list[int], potions: list[int], success: int) -> list[int]:
        ans = []
        for s in spells:
            count = 0
            for p in potions:
                if s * p >= success:
                    count += 1
            ans.append(count)
        return ans

solutions.optimal:
class Solution:
    def successfulPairs(self, spells: list[int], potions: list[int], success: int) -> list[int]:
        potions.sort()
        m = len(potions)
        ans = []
        for s in spells:
            need = (success + s - 1) // s
            lo, hi = 0, m
            while lo < hi:
                mid = (lo + hi) // 2
                if potions[mid] < need:
                    lo = mid + 1
                else:
                    hi = mid
            ans.append(m - lo)
        return ans

